def compute(vars):
    old_value = vars["v1"]
    new_value = vars["v2"]
    increase = new_value - old_value

    return {
        "value": increase,
        "trace": {
            "old_value": old_value,
            "new_value": new_value,
            "increase": increase,
            "output_meta": {
                "currency": "USD",
                "scale": None,
                "unit": None
            }
        }
    }
